class Codec:
    def encode(self, strs: list[str]) -> str:
        parts: list[str] = []
        for word in strs:
            parts.append(f"{len(word)}#{word}")  # viz:piece
        return "".join(parts)  # viz:joined

    def decode(self, s: str) -> list[str]:
        strs: list[str] = []
        i = 0
        while i < len(s):
            j = s.index("#", i)  # viz:find
            n = int(s[i:j])  # viz:header
            strs.append(s[j + 1 : j + 1 + n])  # viz:cut
            i = j + 1 + n
        return strs  # viz:done

